import{z as s,x as A,o as t,c as B,q as i,j as o,D as e,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"主机托管与微波","description":"","frontmatter":{"title":"主机托管与微波","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/colocation-microwave.md","filePath":"quant/colocation-microwave.md","lastUpdated":1791063341000}'),d={name:"quant/colocation-microwave.md"};function p(h,a,c,u,m,C){const E=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="主机托管与微波" tabindex="-1">主机托管与微波 <a class="header-anchor" href="#主机托管与微波" aria-label="Permalink to &quot;主机托管与微波&quot;">​</a></h1><div class="epigraph"><p>把服务器放进交易所机房，买的是到撮合核的对称距离；微波把城际路径从光纤的弯路改成近直线。两者改变的是相对延迟，不是优先规则本身。</p><footer>—— Laughlin, Aguirre and Grundfest, Information Transmission Between Financial Markets in Chicago and New York, The Financial Review, 2014；Budish, Cramton and Shim, QJE, 2015；对照 SEC 对主机托管公平接入的讨论</footer></div><p><a href="/quant/snapshot-incremental-feed">上一课</a>声明了行情通道。本课的缺口是<strong>报文在物理层走哪条路</strong>：主机托管（colocation）把竞速场从城市搬进机笼，微波（及毫米波、自由空间光）把芝加哥–纽约一类路径的时间下限从光纤折射率与绕路改写为近乎直线光速。Budish 等人把连续簿上的速度竞争写成军备竞赛；Laughlin、Aguirre 与 Grundfest（2014）测量城际信息传播。本课写相对延迟如何进入研究声明，不写如何建设或租用一条抢跑链路。A 股对照见<a href="/quant/cn-colocation-rectify">托管整改</a>：公平接入是约束，不是产品差异化菜单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时间优先在核入口裁决。核之前的每一跳——光纤长度、交换机、跨城中继——都在给不同客户不同的「到达时刻」。托管的制度承诺通常是：同一机房同等机笼、同等线长、同等端口，使相对延迟的差小于一个可公布的上限。问题是承诺的边界：跨城的另一所、SIP 汇总点、期货与股票不在同一园区时，托管并不能把全国时钟收成一台。研究跨所领先滞后，必须声明各腿是否托管、是否微波，否则铅滞后里混进了电缆。</p><p><span class="marginnote">光在真空里每秒约 30 万公里，但玻璃的折射率约为 1.5，光在光纤里只剩约 20 万公里/秒。芝加哥到纽约大圆距离约 1150 公里：微波走近直线单程约 6 毫秒，光纤既要绕铁路公路、又要打七折速度，一来一回就慢出好几毫秒——这正是 2014 年那篇测量文章盯住的差。</span></p><p>微波的物理：光纤沿铁路公路走，几何路径长于大圆；玻璃折射率使传播慢于真空光速。微波塔近直线、近空气光速，城际可以快若干毫秒。这改变指数期货与 ETF 之间的信息到达顺序，不改变本所 FIFO。把「微波 alpha」写进因子库，其实是在写一条时变的通讯技术路径，路径一变，样本外立即失效。</p><h3 id="公平接入与「同等线长」不是零延迟" tabindex="-1">公平接入与「同等线长」不是零延迟 <a class="header-anchor" href="#公平接入与「同等线长」不是零延迟" aria-label="Permalink to &quot;公平接入与「同等线长」不是零延迟&quot;">​</a></h3><p>托管费买的是分布的对称，不是绝对零。交换机仍有排队，网卡仍有抖动，邻居流量仍能造成微突发。交易所公布的延迟数字往往是中位或最佳，研究要用尾部：99 分位才打进核的入队。A 股程序化细则要求会员提供交易单元与托管时遵循公平原则，不得为程序化投资者提供特殊便利；把境外「付费买更短线」的故事直接套到沪深股票竞价，与公开规则不符。</p><p><span class="marginnote">初学者容易以为交易所公布的延迟数字就是自己会得到的延迟。实际上那往往是中位数甚至最佳值：交换机排队、邻居的微突发都只发生在尾部，99 分位可能比中位数差出一个数量级。研究必须用尾部数字——99 分位才打进核的入队，中位数只是营销。</span></p><p><span class="marginnote">芝加哥 CME 与纽约 Nasdaq 园区之间的路径是经典测量对象。A 股对应的是上交所与中金所、深市与沪市之间的光纤，以及国际投资者经港股通的额外跳数。数字不同，要声明的对象相同：哪两台时钟、哪两种物理介质。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>延迟预算表按跳填写：策略主机 → 园区交换机 → 网关 → 撮合核；行情反向再走一遍。每跳标注介质（光纤/微波/本地铜缆）、是否托管、是否共享交换机。回测若假设「信号与成交同一瞬间」，等于删掉这张表。</p>',13)),(t(),o(l,null,{default:e(()=>[r(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Host%5B%22%E7%AD%96%E7%95%A5%E4%B8%BB%E6%9C%BA%EF%BC%88%E6%89%98%E7%AE%A1%E6%9C%BA%E7%AC%BC%E5%86%85%EF%BC%89%22%5D%20--%3E%7C%22%E7%BD%91%E5%8D%A1%20%2B%20%E9%93%9C%E7%BC%86%22%7C%20Switch%5B%22%E5%9B%AD%E5%8C%BA%E4%BA%A4%E6%8D%A2%E6%9C%BA%22%5D%0A%20%20Switch%20--%3E%7C%22%E6%8E%92%E9%98%9F%E4%B8%8E%E6%8A%96%E5%8A%A8%22%7C%20GW%5B%22%E7%BD%91%E5%85%B3%22%5D%0A%20%20GW%20--%3E%7C%22%E6%9C%AC%E5%9C%B0%E5%85%89%E7%BA%A4%22%7C%20Core%5B%22%E6%92%AE%E5%90%88%E6%A0%B8%E5%85%A5%E5%8F%A3%20FIFO%22%5D%0A%20%20Feed%5B%22%E8%A1%8C%E6%83%85%E5%89%8D%E6%9C%BA%22%5D%20--%3E%7C%22%E5%8F%8D%E5%90%91%E5%90%8C%E4%B8%80%E8%B7%AF%E5%BE%84%22%7C%20Host%0A%20%20MW%5B%22%E5%9F%8E%E9%99%85%E5%BE%AE%E6%B3%A2%E5%A1%94%22%5D%20-.-%3E%7C%22%E8%B7%A8%E6%89%80%E8%85%BF%E5%8F%A6%E7%AE%97%22%7C%20GW%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>跨市场事件研究：用两所官方时间戳（需先经后课 PTP 校准）估计信息领先，再单独报告传输层可解释的部分。不能解释的残差才可能是经济领先；把电缆当 alpha 会高估发现能力。</p><p>比较研究应固定产品、固定日期、变的是接入方式：托管 vs 城外、光纤 vs 微波。结果报告的是到达时间分布，不是夏普。容量与费用：托管机笼、交割端口、微波租用是固定成本，进入<a href="/quant/live-capacity-estimate">实盘容量</a>的成本函数，而不是进入因子 IC。</p><h3 id="相对延迟会改写观测到的「毒性」" tabindex="-1">相对延迟会改写观测到的「毒性」 <a class="header-anchor" href="#相对延迟会改写观测到的「毒性」" aria-label="Permalink to &quot;相对延迟会改写观测到的「毒性」&quot;">​</a></h3><p>同一笔主动单，慢行情用户看见的 BBO 已过时，其限价单更容易被扫，表面上「被选中」。这是信息到达差，不必是对手有更强的私人信息。计量上应把接入类型当账户协变量，或至少当样本分层，否则<a href="/quant/toxic-flow">订单流毒性</a>会把基础设施差异写成逆向选择。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续 LOB 把无穷小时间差变成排队权。物理层把时间差变成可购买的输入。军备竞赛的均衡是：相对延迟被压到技术下限，绝对福利未必增加——这是 Budish 等建议频繁集合竞价的动机。托管对称化本所内部；微波改变所与所之间。两者都不改核内优先公式，只改谁的报文先成为该公式的输入。</p><p>行情与订单若走不同介质，会出现「行情已到、订单通道更慢」或反向。做市策略的报价更新与撤单必须按更慢的那条腿预算，否则你在用快行情决定一张慢撤单，等于把过时报价留在簿上。这是风险，不是优化空间；本课到此停止。</p><p><span class="marginnote">可以把它想象成看直播抢票：直播画面（行情腿）比你手里的提交按钮（订单腿）快半秒，你看到「还有余票」时按下按钮，座位早被别人拿走了。两条腿不对称时，决策依据的行情永远是过时的，按更慢那条腿做预算就是在校准这个时间差。</span></p>',8)),(t(),o(l,null,{default:e(()=>[r(E,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20ExA%5B%22%E4%BA%A4%E6%98%93%E6%89%80%20A%20%E6%A0%B8%22%5D%20--%3E%20Fiber%5B%22%E5%85%89%E7%BA%A4%E7%BB%95%E8%B7%AF%22%5D%0A%20%20ExA%20--%3E%20MW%5B%22%E5%BE%AE%E6%B3%A2%E8%BF%91%E7%9B%B4%E7%BA%BF%22%5D%0A%20%20Fiber%20--%3E%20HostB%5B%22%E5%9F%8E%E5%B8%82%20B%20%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20MW%20--%3E%20HostB%0A%20%20Colo%5B%22%E6%9C%AC%E6%89%80%E6%89%98%E7%AE%A1%E6%9C%BA%E7%AC%BC%22%5D%20--%3E%20ExA%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供链路勘察、租塔、或利用非对称接入损害其他投资者的方案。监管对公平接入、程序化托管的限制以现行公开规则为准。卫星、海底光缆、跨境互连有另外的时间尺度，不能用芝加哥–纽约微波的毫秒数去填。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>托管对称化本所相对延迟；微波改写城际信息到达，二者都不改核内 FIFO。</li><li>研究必须声明接入与介质，否则领先滞后与毒性混进电缆。</li><li>A 股托管受公平接入与程序化规则约束，不能按境外付费抢跑来建模。</li><li>出处：Laughlin, Aguirre and Grundfest, <em>The Financial Review</em>, 2014；Budish, Cramton and Shim, <em>QJE</em>, 2015。</li></ul>',4))])}const q=s(d,[["render",p]]);export{f as __pageData,q as default};
